mapper.select:
SELECT id AS oper_id, authorization_id, tid, parent_id, module_prefix, from_app, api_module, menu_id,
       oper_subject, api_description, method, request_url, request_method,
       terminal, terminal_detail, oper_name,
       request_param, response_data, error_msg, status,
       request_time, response_time, consume_mill,
       create_op, create_time, modify_op, modify_time
FROM log_operation
WHERE deleted = 0
  AND from_app = 'gateway'
  AND parent_id IS NULL

    AND authorization_id = #{query.authorizationId}


    AND tid = #{query.tid}


    AND module_prefix = #{query.modulePrefix}


    AND oper_name LIKE CONCAT('%', #{query.operName}, '%')


    AND request_url LIKE CONCAT('%', #{query.requestUrl}, '%')


    AND request_method = #{query.requestMethod}


    AND status = #{query.status}


    AND request_time >= #{query.requestTimeStart}


    AND request_time <= #{query.requestTimeEnd}


    ORDER BY ${query.orderByColumn}


    ORDER BY request_time DESC

SELECT id
FROM log_operation
WHERE request_time < #{expiredBefore}
ORDER BY request_time ASC
LIMIT #{batchSize}
